use vstd::prelude::*;

verus! {
    // copyto: for each index i, picks src[i] if mask[i] is true, otherwise dst[i].
    fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> (result: Vec<T>)
        requires
            dst.len() == src.len(),
            src.len() == mask.len(),
        ensures
            result.len() == dst.len(),
            forall |i: usize| i < dst.len() ==>
                (if mask[i] { result[i] == src[i] } else { result[i] == dst[i] }),
    {
        let n = dst.len();
        let mut i: usize = 0;
        let mut result: Vec<T> = Vec::new();
        // Build up result one element at a time.
        while i < n
            invariant
                // loop index does not exceed length
                i <= n,
                // result has exactly i elements so far
                result.len() == i,
                // for all j < i, the selection rule holds
                forall |j: usize| j < i ==>
                    (if mask[j] { result[j] == src[j] } else { result[j] == dst[j] }),
                // input lengths stay constant
                dst.len() == n,
                src.len() == n,
                mask.len() == n,
            decreases n - i,
        {
            if mask[i] {
                // T: Copy so src[i] is a copyable value
                result.push(src[i]);
            } else {
                result.push(dst[i]);
            }
            i = i + 1;
        }
        result
    }
}

